class MapNotLoadedException(Exception):
    pass


class WaitAborted(Exception):
    "Raised inside a wait for the user when the wait hook asks to stop waiting (master-learn switched off)."


class TelemetryTimeout(Exception):
    pass


class Tmenv(Env):
    def __init__(
        self,
        name,
        width,
        height,
        prefix_path=None,  # Linux only
        prefix_template_path=None,  # Linux only
        credential_path=None,  # Linux only
        timestep=0.1,
        wait_telemetry=True,
        telemetry_time=0.001,
        telemetry_timeout=0.5,
        action_handler=DiscreteActionHandler(),
        device="cpu",
        window_x=0,
        window_y=0,
        game_kwargs=None,  # Windows only, extra `WinGame` arguments (port, launch, analog_steer, ...)
        fixed_period=False,  # keep actions `timestep` apart by shortening the sleep by the processing time
        min_action_delay=0.03,  # fixed_period: shortest sleep between an action and its observation
        passive=False,  # master-learn: the user drives, the env only observes and reads their inputs
    ):
        self.name, self.width, self.height = name, width, height
        self.game_kwargs = game_kwargs or {}
        self.fixed_period, self.min_action_delay = fixed_period, min_action_delay
        self.passive, self.last_user_action, self.stop_check = passive, None, None
        self.wait_hook = None  # callable polled while waiting for the user; True aborts the wait
        self._prev_racetime = None
        self._obs_time = self._last_act_time = self._last_delay = self._overhead_ema = self._period_ema = None
        self.prefix_path = prefix_path
        self.prefix_template_path = prefix_template_path
        self.credential_path = credential_path
        self.timestep = timestep
        self.wait_telemetry = wait_telemetry
        self.telemetry_time = telemetry_time
        self.telemetry_timeout = telemetry_timeout
        self.action_handler = action_handler
        self.device = device
        self.window_x, self.window_y = window_x, window_y
        self.action_space = self.action_handler.action_space
        self.observation_space = Dict({"env": Dict()})

    @property
    def has_map(self):
        return hasattr(self, "map_data")

    @property
    def config(self):
        config = dict(
            name=self.name,
            width=self.width,
            height=self.height,
            timestep=self.timestep,
            action_handler=self.action_handler.name,
        )
        if self.has_map:
            config["map"] = {
                k: self.map_data[k] for k in self.map_data.keys() - ["ghosts"]
            }
        return config

    @cached_property
    def game(self):
        game = self._make_game()
        game.passive = self.passive
        game.stop_check = self.stop_check
        return game

    def _make_game(self):
        if sys.platform == "win32":
            from .win32 import WinGame

            return WinGame(
                self.name,
                self.width,
                self.height,
                self.window_x,
                self.window_y,
                stop_check=self.stop_check,
                **self.game_kwargs,
            )
        return Game(
            self.name,
            self.width,
            self.height,
            self.prefix_path,
            self.prefix_template_path,
            self.credential_path,
            self.window_x,
            self.window_y,
        )

    def recover(self):
        """Relaunch the game in the wine environment. To be used in the event of a crash."""
        logging.warning(f"Recovering Tmenv {self.name}")
        self.game.recover()
        self.game.load_map(self.map_data["url"])
        self.game.toggle_interface()

    def _wait_check(self):
        if self.stop_check is not None:
            self.stop_check()
        if self.wait_hook is not None and self.wait_hook():
            raise WaitAborted()

    def set_passive(self, passive):
        "Master-learn: True = the user drives and the AI only observes (takes effect at the next reset)."
        self.passive = bool(passive)
        if "game" in self.__dict__:
            self.game.passive = self.passive

    def wait_telemetry_update(self):
        start_time = time()
        # The plugin sends nothing while the user's car respawns after a restart: be patient in master-learn
        timeout = self.telemetry_timeout * (10 if self.passive else 1)
        while self.telemetry_time < (time() - self.game.telemetry["_updatetime"]):
            sleep(self.telemetry_time / 2)
            if timeout < time() - start_time:
                raise TelemetryTimeout()
        return (time() - start_time) * 1000

    def env_observation(self):
        if self.wait_telemetry:
            telemetry_lag = self.wait_telemetry_update()
        previous = deepcopy(self.game.previous_telemetry)
        env = deepcopy(self.game.telemetry)
        env["previous"] = previous
        if self.wait_telemetry:
            env["telemetry_lag"] = telemetry_lag
        else:
            env["telemetry_lag"] = (time() - env["_updatetime"]) * 1000
        env["velocity_norm"] = np.linalg.norm(env["velocity"]).item()
        env["crossed_checkpoint"] = False
        env["observation_start_time"] = time()
        return dict(env=env)

    def env_info(self, observation):
        # racetime from telemetry can be bugged at the end of a race
        # and have a negative value
        racetime = observation["env"]["racetime"]
        if 0 < racetime:
            self.last_positive_racetime = racetime
        elif self.last_positive_racetime is not None:
            racetime = self.last_positive_racetime

        return dict(
            checkpoints=self.checkpoints,
            finished=observation["env"]["finished"],
            racetime=racetime,
            must_respawn=False,
            telemetry_lag=observation["env"]["telemetry_lag"],
        )

    def action_delay(self, now):
        "Sleep after the action: `timestep`, or less by the (smoothed) overhead of the previous step."
        if not self.fixed_period:
            return self.timestep
        if self._last_act_time is not None and self._last_delay is not None:
            # Overhead = everything in the previous period that was not the sleep: waiting for a fresh
            # telemetry frame, wrappers building the state, action selection, replay buffer push, callbacks
            overhead = min(max(0.0, (now - self._last_act_time) - self._last_delay), self.timestep)
            self._overhead_ema = overhead if self._overhead_ema is None else 0.8 * self._overhead_ema + 0.2 * overhead
        return max(self.min_action_delay, self.timestep - (self._overhead_ema or 0.0))

    def step(self, action):
        now = time()
        delay = self.action_delay(now)
        if self._last_act_time is not None:
            period = now - self._last_act_time
            self._period_ema = period if self._period_ema is None else 0.9 * self._period_ema + 0.1 * period
        self._last_act_time, self._last_delay = now, delay
        if self.passive:
            # Master-learn: the user drives; their inputs in the middle of the step are the action
            sleep(delay / 2)
            t = self.game.telemetry
            self.last_user_action = self.action_handler.from_inputs(0.5 < t["accelerate"], bool(t["brake"]), t["steer"])
            sleep(delay / 2)
        else:
            self.game.act(**self.action_handler.action_dict(action))
            sleep(delay)
        observation = self.env_observation()
        self._obs_time = time()
        observation["env"]["action_delay"] = delay
        if self.current_landmark != observation["env"]["landmark_index"]:
            observation["env"]["crossed_checkpoint"] = True
            self.current_landmark = observation["env"]["landmark_index"]
            self.checkpoints.append(observation["env"]["racetime"])
            if observation["env"]["landmark_index"] == observation["env"]["standing_landmark_index"]:
                self.standing_cp_offset = 0
            else:
                self.standing_cp_offset -= 1
        done = observation["env"]["finished"]
        info = self.env_info(observation)
        info["step_period"] = (self._period_ema or 0.0) * 1000
        info["user_action"] = self.last_user_action if self.passive else None
        racetime = observation["env"]["racetime"]
        if self.passive and self._prev_racetime is not None and racetime < self._prev_racetime - 200:
            done = True  # the user restarted the race: this episode ends, reset() waits for the new start
            info["user_restart"] = True
        self._prev_racetime = racetime
        return observation, 0.0, done, info

    def respawn(self, launched=True):
        if not self.passive:
            self.game.act(**self.action_handler.default_action_dict)
            self.game.respawn(launched, wait_go=True)
        observation = self.env_observation()
        self._obs_time, self._last_act_time = time(), None
        return observation

    def reset(self, **kwargs):
        if not self.has_map:
            raise MapNotLoadedException("Call load_map method first")
        if self.passive:
            logging.info(f"{self.name} master-learn: waiting for you to (re)start the race (Delete restarts it)")
            try:
                self.game.wait_user_start(self._wait_check)
            except WaitAborted:
                logging.info(f"{self.name} master-learn switched off while waiting: the AI drives")
        if not self.passive:
            self.game.act(**self.action_handler.default_action_dict)
            self.game.give_up(wait_go=True)
        observation = self.env_observation()
        self._obs_time, self._last_act_time = time(), None
        self._prev_racetime = observation["env"]["racetime"]
        self.current_landmark = observation["env"]["landmark_index"]
        self.checkpoints = []
        self.standing_cp_offset = 0 # 0 for same as current cp, -2 if last standing cp was 2 cps ago
        self.last_positive_racetime = None
        return observation

    def load_map(self, map_uid="XJ_JEjWGoAexDWe8qfaOjEcq5l8"):  # Summer 2020 - 01
        if self.has_map and self.map_data["uid"] == map_uid:
            logging.debug(f"{self.name} has already loaded map uid {map_uid}")
            return
        logging.debug(f"{self.name} is loading map uid {map_uid}")
        self.map_data = map_from_uid(map_uid)
        self.game.load_map(self.map_data["url"])
        self.game.toggle_interface()

    def close(self):
        if "game" in self.__dict__:
            self.__dict__["game"].close()
